import java.util.*;
import java.io.*;

public class Main {
    static long[][] C = new long[62][62];
    static long[][] A = new long[32][32];
    static long[][] B = new long[32][32];
    static long totalComb;
    static int R, Cc, n;
    static char[] p = new char[110];
    static long[][] CC = new long[32][32];
    static long maxDiff;
    static List<long[]>[][] P = new ArrayList[32][2];
    static List<long[]>[][] Q = new ArrayList[32][2];
    static long Result = 0;
    static long totalRes = 0;

    static {
        for (int i = 0; i < 32; i++) {
            for (int j = 0; j < 2; j++) {
                P[i][j] = new ArrayList<>();
                Q[i][j] = new ArrayList<>();
            }
        }
    }

    static void addPath(int x, int y, long g, long c1, long c2, int ck) {
        if (x + y == R + n) {
            P[x][ck].add(new long[]{g, c1});
            if (c2 != 0) Q[x][ck].add(new long[]{g, c2});
            return;
        }
        addPath(x + 1, y, g + (!ck != 0 ? A[x + 1][y] : 0), c1, (p[x + y] != 'B' ? c2 : 0), ck);
        addPath(x, y + 1, g + (ck != 0 ? B[x][y + 1] : 0), c1, (p[x + y] != 'A' ? c2 : 0), ck);
    }

    static void calcMin(int x, int y, long g, int ck) {
        if (x + y == R + n) {
            List<long[]> list = P[x][ck];
            if (list.isEmpty()) return;
            int t = lowerBound(list, (totalComb + 1) / 2 - g);
            if (t != list.size() && list.get(t)[1] > 0) {
                long tp = (list.get(t)[0] + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff > tp) maxDiff = tp;
            }
            if (t > 0 && list.get(t - 1)[1] > 0) {
                long tp = (list.get(t - 1)[0] + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff > tp) maxDiff = tp;
            }
            return;
        }
        if (x > 0) calcMin(x - 1, y, g + (!ck != 0 ? A[x][y] : 0), ck);
        if (y > 0) calcMin(x, y - 1, g + (ck != 0 ? B[x][y] : 0), ck);
    }

    static void calcMax(int x, int y, long g, int ck) {
        if (x + y == R + n) {
            List<long[]> list = Q[x][ck];
            int t = lowerBound(list, (totalComb + 1) / 2 - g);
            if (t != list.size() && list.get(t)[1] > 0) {
                long tp = (list.get(t)[0] + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff == tp) {
                    totalRes += list.get(t)[1];
                }
            }
            if (t > 0 && list.get(t - 1)[1] > 0) {
                long tp = (list.get(t - 1)[0] + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff == tp) {
                    totalRes += list.get(t - 1)[1];
                }
            }
            return;
        }
        if (p[x + y - 1] != 'B') calcMax(x - 1, y, g + (!ck != 0 ? A[x][y] : 0), ck);
        if (p[x + y - 1] != 'A') calcMax(x, y - 1, g + (ck != 0 ? B[x][y] : 0), ck);
    }

    static void compress(List<long[]> P) {
        if (P.isEmpty()) return;
        P.sort(Comparator.comparingLong(a -> a[0]));
        int cnt = 0;
        long sum = 0;
        List<long[]> newP = new ArrayList<>();
        for (int i = 0; i < P.size(); i++) {
            sum += P.get(i)[0];
            if (i == P.size() - 1 || P.get(i)[0] != P.get(i + 1)[0]) {
                newP.add(P.get(i));
                cnt++;
                sum = 0;
            }
        }
        P.clear();
        P.addAll(newP);
    }

    static int lowerBound(List<long[]> list, long value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid)[0] >= value) high = mid;
            else low = mid + 1;
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        Cc = Integer.parseInt(st.nextToken());
        p = br.readLine().toCharArray();

        for (int i = 0; i <= 61; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
        n = R + Cc;
        totalComb = C[n * 2][R * 2];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i > 0) A[i][j] = C[i - 1][R - 1] * (C[n * 2 - i][R] - C[j][R]);
                if (j > 0) B[i][j] = C[j - 1][R - 1] * (C[n * 2 - j][R] - C[i][R]);
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                compress(P[i][j]);
                compress(Q[i][j]);
            }
        }

        maxDiff = totalComb + 1;
        calcMin(n, n, 0, 0);
        calcMin(n, n, 0, 1);
        calcMax(n, n, 0, 0);
        calcMax(n, n, 0, 1);

        System.out.println(totalRes);
    }
}
